return $input.all().map(i => {
  const j = i.json;
  if (!j.rep_email) return null;
  let brief = j.raw_payload;
  if (typeof brief === 'string') { try { brief = JSON.parse(brief); } catch (e) { brief = null; } }
  const signals = (brief && Array.isArray(brief.signals)) ? brief.signals.slice(0, 4).map(s => `• [${s.date || '—'}] ${s.description || ''}`).join('
') : '(no signals on file)';
  const posture = (brief && brief.posture && brief.posture.headline) || '';
  const move = (brief && brief.element_4 && brief.element_4.the_move) || '';
  const catch_ = (brief && brief.element_4 && brief.element_4.the_catch) || '';
  const bg = (brief && Array.isArray(brief.buying_group)) ? brief.buying_group.map(b => `• ${b.name || '?'} — ${b.title || b.focus_area || ''}`).join('
') : '';
  let touches = j.touches; if (typeof touches === 'string') { try { touches = JSON.parse(touches); } catch (e) { touches = []; } }
  const touchLine = Array.isArray(touches) && touches.length ? touches.map(t => `${t.type} (${t.status})`).join(', ') : 'none yet';
  let eng = j.recent_engagement; if (typeof eng === 'string') { try { eng = JSON.parse(eng); } catch (e) { eng = []; } }
  const engLines = Array.isArray(eng) && eng.length ? eng.map(x => `• ${x.event} — ${String(x.at).slice(0, 16)}`).join('
') : '(none recorded)';
  const when = new Date(j.occurred_at);
  const body = `Meeting prep — ${j.account}
With: ${j.contact || 'unknown contact'}
When: ${when.toISOString().replace('T', ' ').slice(0, 16)} UTC
Objective: ${j.objective || 'not set'}

Posture: ${posture || '—'}
The move: ${move || '—'}
The catch: ${catch_ || '—'}

Recent signals:
${signals}

Buying group:
${bg || '(unknown)'}

What we've sent them: ${touchLine}

Their recent engagement:
${engLines}

Good luck — log the outcome after the call via your digest links or quick-log.`;
  return { json: { event_id: j.id, rep_email: j.rep_email, subject: `Meeting in <45 min: ${j.account}${j.contact ? ' (' + j.contact + ')' : ''} — prep sheet`, body } };
}).filter(Boolean);
